+  return [
+    '\nRun summary',
+    `Elapsed: ${seconds(timings.elapsedMs)}; active: ${seconds(timings.activeMs)} (excludes prompt waits)`,
+    `Evaluation: ${seconds(timings.evaluationMs)}; preparation: ${seconds(timings.preparationMs)}`,
